INSERT INTO `about` (`id`, `about`) VALUES
(1, '<p>Life is becoming too busy to get medical appointments in person and to maintain proper health care. If anybody is ill and wants to visit a doctor for a checkup, he or she needs to visit the hospital and waits until the doctor is available. The patient also waits in a queue while getting an appointment.</p><p>If the doctor cancels the appointment for some emergency reasons then the patient is not able to know about the cancelation of the appointment unless or until he or she visits the hospital. As mobile communication technology is developing rapidly, therefore, one can use mobileâ€™s applications to overcome such problems and inconvenience for the patients.</p><p>The main idea of this platform is to provide ease and comfort to patients while taking an appointment from doctors and it also resolves the problems that the patients have to face while making an appointment. Our portfolio includes some of the high-performing appointment booking solutions for leading organizations.</p><p>We combine our technical skills and innovative ideas to deliver a solution that meets the requirements in the best possible way. The solutions delivered by us eliminate the gap between patients and doctors. They give patients the flexibility to book their appointment with the doctor in their neighborhood.</p><p>&nbsp;</p>');

