CREATE TABLE `privacy_policy` (
  `id` int(11) NOT NULL,
  `privacy_policy` text NOT NULL
) ENGINE=MyISAM DEFAULT CHARSET=latin1;

--
-- Dumping data for table `privacy_policy`
--

INSERT INTO `privacy_policy` (`id`, `privacy_policy`) VALUES
(1, '<p><strong>PRIVACY</strong></p><p>MyMediApp (\"us\", \"we\", or \"MyMediApp\", which also includes its affiliates) is the author and publisher of the internet resource www.MyMediApp.com (\"Website\") on the world wide web as well as the software and applications provided by MyMediApp, including but not limited to the mobile application MyMediApp, and the software and applications of the brand names MyMediApp (together with the Website, referred to as the \"Services\").</p><p><strong>General</strong></p><p>We will not sell, share or rent your personal information to any 3rd party or use your email address/mobile number for unsolicited emails and/or SMS. Any emails and/or SMS sent by Razorpay will only be in connection with the provision of agreed services &amp; products and this Privacy Policy. Periodically, we may reveal general statistical information about Razorpay &amp; its users, such as the number of visitors, number and type of goods and services purchased, etc. We reserve the right to communicate your personal information to any third party that makes a legally-compliant request for its disclosure.</p><p><strong>Personal Information</strong></p><p>Personal Information means and includes all information that can be linked to a specific individual or to identify any individual, such as name, address, mailing address, telephone number, email ID, credit card number, cardholder name, card expiration date, information about your mobile phone, DTH service, data card, electricity connection, Smart Tags and any details that may have been voluntarily provided by the user in connection with availing any of the services on Razorpay When you browse through Razorpay, we may collect information regarding the domain and host from which you access the internet, the Internet Protocol [IP] address of the computer or Internet service provider [ISP] you are using, and anonymous site statistical data.</p><p><strong>Use of Personal Information</strong></p><p>We use personal information to provide you with services &amp; products you explicitly requested for, to resolve disputes, troubleshoot concerns, help promote safe services, collect money, measure consumer interest in our services, inform you about offers, products, services, updates, customize your experience, detect &amp; protect us against error, fraud, and other criminal activity, enforce our terms and conditions, etc. We also use your contact information to send you offers based on your previous orders and interests. We may occasionally ask you to complete optional online surveys. These surveys may ask you for contact information and demographic information (like zip code, age, gender, etc.). We use this data to customize your experience at Paytm, providing you with content that we think you might be interested in and to display content according to your preferences.</p><p><strong>Cookies</strong></p><p>A \"cookie\" is a small piece of information stored by a web server on a web browser so it can be later read back from that browser. Paytm uses cookie and tracking technology depending on the features offered. No personal information will be collected via cookies and other tracking technology; however, if you previously provided personally identifiable information, cookies may be tied to such information. Aggregate cookie and tracking information may be shared with third parties.</p><p><strong>Links to Other Sites</strong></p><p>Our site links to other websites that may collect personally identifiable information about you. Razorpay is not responsible for the privacy practices or the content of those linked websites.</p><p><strong>Security</strong></p><p>Paytm has stringent security measures in place to protect the loss, misuse, and alteration of the information under our control. Whenever you change or access your account information, we offer the use of a secure server. Once your information is in our possession we adhere to strict security guidelines, protecting it against unauthorized access.</p><p><strong>Consent</strong></p><p>By using Paytm and/or by providing your information, you consent to the collection and use of the information you disclose on Paytm in accordance with this Privacy Policy, including but not limited to your consent for sharing your information as per this privacy policy. The name and contact details of the CEO are provided below: Vill- BIDHANPALLY, PO+PS-DALKHOLA, DistUttar Dinajpur, WB-733201 Time: Mon-Sat (9:00 am â€” 6:00 pm)</p><p><strong>Contact Us -</strong>&nbsp;9382215035, and&nbsp;<strong>Email -</strong>&nbsp;mymediapp@gmail.com</p>');

