INSERT INTO `webdetails` (`id`, `vendor_id`, `vendor_url`, `favicon`, `thumb_favicon`, `thumb_logo`, `logo`, `title`, `address`, `mobile`, `email`, `website`, `terms`, `privacy`, `return`, `refund`, `disclaimer`, `wallet_policy`, `faqs`, `about`, `fb_link`, `twitter_link`, `insta_link`, `youtube_link`, `minimum_amount`, `shipping_charge`, `gst_number`, `city`, `country`, `state`, `description`, `whatsapp`, `twakto`, `flag`) VALUES
(3, 1, 'barevalue.com', '202208030022logo.jpg', '', 'assets/uploads/thumb/logo/3549logo.jpg', '202208020100logo.jpg', 'TACA', 'Burari, Delhi-84', 0, 'vickyrocks2593@gmail.com', 'rythmicalchords.com', '<h3>Terms & Conditions</h3>\n\n<p><strong>Acceptance.</strong> By using the Website or Services in any manner, you are bound by these Terms of Service, as well as the Incorporated Terms identified below (collectively, the “<strong>Terms</strong>”). If you do not agree to the Terms, then do not use the Website or Services. If you are accepting these Terms on behalf of a company, organization, government, or other legal entity, you represent and warrant that <strong>(a)</strong> you are authorized to do so, <strong>(b)</strong> the entity agrees to be legally bound by the Terms, and <strong>(c)</strong> neither you nor the entity are barred from using the Services or accepting the Terms under the laws of the applicable jurisdiction.</p>\n\n<p><strong>Scope.</strong> These Terms govern your use of the Website and the Services. Except as otherwise specified, these Terms do not apply to Third-Party Products, which are governed by their own terms of service.</p>\n\n<p><strong>Registration.</strong> In order to use the Services, you must establish a Services account (“<strong>Account</strong>”) by registering with Orangeapes. You may be required to submit a valid means of payment for which you are authorized to purchase Services. You will provide true, accurate, current, and complete information when registering for an Account and will update the information as necessary to keep your Account and payment information current. As part of the registration process, you will provide BigCommerce with a user name and password for your Account (together “<strong>Account Credentials</strong>”). Orangeapes reserves the right to refuse registration of, or cancel, accounts that violate these Terms or orangeapes Acceptable Use Policy.</p>\n\n<p><strong>Security.</strong></p>\n\n<p><strong>Generally</strong>. You are responsible for maintaining the security of your Account Credentials and for all Services ordered, accessed, or otherwise used in connection with your Account Credentials and all actions taken in association therewith. You will not share your Account Credentials with any third party.</p>\n\n<p><strong>Payment Cards</strong>. Orangeapesv is responsible for the security of credit cardholder data to the extent that orangeapes has control of that data. To that end, orangeapes undertakes regular assessments consistent with the applicable Payment Card Industry Data Security Standards (“<strong>PCI</strong>”). You represent and warrant that you will determine the PCI merchant requirements applicable to you and your use of the Services.</p>\n\n<p><strong>Checkout Environment; PCI</strong>. Orangeapes will provide a secure environment (including appropriate technical, physical and organizational security measures and safeguards) for customer data stored and processed via the standard orangeapes checkout (“<strong>Customer Data</strong>”) in order to protect Customer Data from unauthorized access and use. orangesapes secure environment is certified under the Payment Card Industry Data Security Standard. orangeapes will maintain PCI certification for the designated portions of the Services that you use to store and process credit card data, subject to the following (each a “<strong>PCI Compliance Condition</strong>”): (i) you comply with orangeapes documentation and in-product notifications, and (ii) you use a orangeapes checkout environment that has not been modified except through the orangeapes control panel. To the extent permitted by applicable law, orangeapes excludes and disclaims any liability related to the unauthorized use of Customer Data, including liability due to PCI noncompliance, in the event any PCI Compliance Condition is not satisfied. For example, you will be solely liable for PCI compliance with respect to modifications to the checkout environment, including modifications via apps or a developer, modifications of BigCommerce&#39;s distributed open source checkout code in any manner that could result in or contribute to PCI noncompliance, use of a checkout environment not provided by orangeapes , or use of a payment provider for which orangeapes does not provide an integration.</p>\n\n<p><strong>Feedback.</strong> You may provide orangeapes with ideas, opinions, recommendations, feedback, or advice in connection with your use of the Services (collectively, \"<strong>Feedback</strong>\"). If you submit Feedback to orangeapes , you hereby grant orangeapes an irrevocable, perpetual, transferable, non-exclusive, fully-paid-up, royalty-free, worldwide license (sublicensable through multiple tiers) to: (a) use, copy, distribute, reproduce, modify, create derivative works of, adapt, publish, translate, publicly perform, and publicly display such Feedback (or any modification thereto), in whole or in part, in any format, medium or application now known or later developed; and (b) use, and permit others to use, Feedback in any manner and for any purpose (including, without limitation, commercial purposes) that orangeapes deems appropriate in its discretion (including, without limitation, incorporating Feedback, in whole or in part, into any technology, product or service).</p>\n\n<p>I hereby authorize and give consent to <strong>Axepert Exhibits Pvt. Ltd.</strong> to send me, either through itself or through any third party service provider, from time to time various information/alerts / SMS/ other messages or calls or commercial communication, and other services on the aforesaid listed telephone numbers, whether these numbers are registered with National Do Not Call Registry/ listed in National Customer Preference Register or not. I also confirm that by sending any of such messages / calls, I will not hold ASBL its third party service provider liable / institute complaint under the Telecom Commercial Communications Customer Preference (TRAI) Regulations, 2010 or such other applicable regulations including any amendment thereof, as may be applicable from time to time. It will be auto renewed every month and if you want to stop this service please write an email to <a href=\"mailto: mail@axepertexhibits.com\">mail@axepertexhibits.com</a> before the due date and call our support number <a href=\"tel: 9899324415\">+91 9899324415</a> also once the amount is debited from account it will not be refunded.</p>', '<h3><strong>Privacy Policy</strong></h3>\r\n\r\n<p>Orangeapes wants to help you better understand how we collect, use, protect, and share your personal data. This Privacy Policy is designed to help you understand your privacy choices when you visit our site, use our mobile app or any of our services. It does not apply to other websites or services that we do not control, including websites or services of other orangeapes users.</p>\r\n\r\n<p>This Privacy Policy is incorporated into, and forms an integral part of, the orangeapes Terms of Service. Capitalized terms have the meanings ascribed them in the Definitions section or our&nbsp;<a href=\"https://www.bigcommerce.com/terms/\"><strong>Terms of Service</strong></a>. Please note that our services may vary by region.</p>\r\n\r\n<p>We encourage you to read this Privacy Policy carefully and take the time to get to know our practices. If you have questions about this Privacy Policy or our privacy practices, please contact us at&nbsp;&nbsp;<a href=\"mailto:privacy@bigcommerce.com\">mail@axepertexhibits.com</a></p>\r\n\r\n<ul>\r\n	<li><strong>Information Types</strong>.\r\n\r\n	<ol>\r\n		<li>&ldquo;<strong>Account Information</strong>&rdquo; means data about how and when a Orangeapes account is accessed and the features used, including Store Information.</li>\r\n		<li>&ldquo;<strong>Browser Information</strong>&rdquo; means provided by a browser, including the IP address, the website visited, network connection, device information, and other data, including Cookies.</li>\r\n		<li>&ldquo;<strong>Contact Information</strong>&rdquo; means basic personal and business information, such as first and last name, company name, email address, postal address, phone number, and may include social media account information.</li>\r\n		<li>&ldquo;<strong>Device Information</strong>&rdquo; means information about your device, such as device ID number, model, and manufacturer, version of your operating system and geographical region, collected from any devices when accessing our website, using the Mobile App, or any of our services.</li>\r\n		<li>&ldquo;<strong>Payment Information</strong>&rdquo; means, for example, credit card, ACH or other payment information.</li>\r\n		<li>&ldquo;<strong>Security Information</strong>&rdquo; means user ID, password and password hints, and other security information used for authentication and account access.</li>\r\n		<li>&ldquo;<strong>Store Information</strong>&rdquo; means information about your store, its products, and its architecture.</li>\r\n		<li>&ldquo;<strong>Support Information</strong>&rdquo; includes information about your hardware and software, authentication data, chat session contents, error reports, performance data, and other communication or technical information and may, with express permission, include remote access to facilitate troubleshooting.</li>\r\n		<li>&ldquo;<strong>Transaction Information</strong>&rdquo; means the data related to transactions that occur on our platform, including product, order, shipping information, Contact Information, and Payment Information.</li>\r\n		<li>&ldquo;<strong>Usage Information</strong>&rdquo; means information collected when you interact with the orangeapes website, mobile application or any of our services, including functionalities accessed, pages visited, and other interaction data.</li>\r\n		<li>&ldquo;<strong>Automated Decision Making</strong>&rdquo; means a decision made solely by automated means without human involvement.</li>\r\n		<li>&ldquo;<strong>Controller</strong>&rdquo; means an entity that determines the purposes and means of the Processing of Personal Data.</li>\r\n		<li>&ldquo;<strong>Cookie</strong>&rdquo; a small file that resides on your computer&rsquo;s hard drive that often contains an anonymous unique identifier that is accessible by the website that placed it there, but is not accessible by other sites.</li>\r\n		<li>&ldquo;<strong>Merchant</strong>&rdquo; means an entity that has used or is using the services for ecommerce.</li>\r\n		<li>&ldquo;<strong>Partner</strong>&rdquo; means a separate legal entity that is a participant in our Agency Partner Program, our Technology Partner Program or other third-party technology integration with the BigCommerce platform, a theme designer, reseller, or referrer of the services.</li>\r\n		<li>&ldquo;<strong>Personal Data</strong>&rdquo; or &ldquo;Personal Information&rdquo; means information that (i) relates to an identified or identifiable natural person, or (ii) identifies, relates to, describes, is capable of being associated with, or could reasonably be linked, directly or indirectly, with a particular consumer or household.</li>\r\n		<li>&ldquo;<strong>Processing</strong>&rdquo; means any operation or set of operations which is performed upon Personal Data, whether or not by automatic means, including, but not limited to, alteration, collection, organization, recording, retrieval, storage, transmission, and use.</li>\r\n		<li>&ldquo;<strong>Processor</strong>&rdquo; means the entity which processes Personal Data on behalf of the Controller.</li>\r\n		<li>&ldquo;<strong>Sensitive Personal Data</strong>&rdquo; means any data that reveals racial or ethnic origin, political opinions, religious or philosophical beliefs, trade union membership, genetic data, biometric data for the purpose of uniquely identifying a natural person, or data concerning health or a natural person&rsquo;s sex life and/or sexual orientation.</li>\r\n		<li>&ldquo;<strong>Shopper</strong>&rdquo; means an entity or natural person that interacts with the ecommerce offering of a Merchant through the BigCommerce platform.</li>\r\n	</ol>\r\n	</li>\r\n</ul>\r\n\r\n<p><strong>Merchants.</strong></p>\r\n\r\n<ol>\r\n	<li><strong>Merchant Policies</strong>. Merchants should help Shoppers understand how the Merchant, orangeapes and relevant third parties collect and process Shoppers&rsquo; Personal Data. To that end, Merchants must:\r\n\r\n	<ul>\r\n		<li>post an accurate privacy policy on their storefront that complies with all applicable laws and regulations;</li>\r\n		<li>process Personal Data in accordance with applicable laws and, to the extent required under such laws, provide notice to and obtain informed consent from Shoppers for the use and access of their Personal Data by orangeapes and other third parties; and</li>\r\n		<li>if the Merchant is collecting any Sensitive Personal Data from Shoppers, obtain affirmative, explicit, and informed consent and allow such Shoppers to revoke their consent to the use and access of Sensitive Personal Data at any time.</li>\r\n	</ul>\r\n	</li>\r\n</ol>\r\n\r\n<p><strong>Visitors.</strong></p>\r\n\r\n<ol>\r\n	<li><strong>Information Collected.</strong>&nbsp;When visitors browse our Website, or engage in communications with us online or offline, we may collect and control, as applicable, Browser Information, Support Information, Contact Information, and Usage Information submitted or communicated to us.</li>\r\n	<li><strong>Information Usage.</strong>&nbsp;We use this information as a Controller to provide our services, and improve and personalize communications, interactions, our services, and provide support if needed. We may use this information in other cases where the Visitor has given express consent.</li>\r\n</ol>', '<h3><strong>Return Policy</strong></h3>\n\n<p><em>Option 1 – No Refunds/Exchanges:</em></p>\n\n<p>We do not accept returns or exchanges unless the item you purchased is defective. If you receive a defective item, please contact us at <strong>[•] </strong>with details of the product and the defect. You can send the item you consider defective to:</p>\n\n<p>Upon receipt of the returned product, we will fully examine it and notify you via e-mail, within a reasonable period of time, whether you are entitled to a refund or a replacement as a result of the defect. If you are entitled to a replacement or refund, we will replace the product or refund the purchase price, using the original method of payment.</p>\n\n<p><em>Option 2 – Refunds Permitted:</em></p>\n\n<p> </p>\n\n<p>We accept returns. You can return unopened items in the original packaging within 30 days of your purchase with receipt or proof of purchase. If 30 days or more have passed since your purchase, we cannot offer you a refund or an exchange.</p>\n\n<p>Upon receipt of the returned item, we will fully examine it and notify you via email, within a reasonable period of time, whether you are entitled to a return. If you are entitled to a return, we will refund your purchase price and a credit will automatically be applied to your original method of payment.</p>\n\n<p>Only regular priced items may be refunded. Sale items are non-refundable.</p>\n\n<p>To follow-up on the status of your return, please contact us at <strong>[•]</strong>.</p>', '<h3><strong>Refund Policy</strong></h3>\n\n<p>We offer refund and/or exchange within the first 30 days of your purchase, if 30 days have passed since your purchase, you will not be offered a refund and/or exchange of any kind.</p>\n\n<p><strong>Eligibility for Refunds and Exchanges</strong></p>\n\n<ul>\n <li>\n <p>Your item must be unused and in the same condition that you received it.</p>\n </li>\n <li>\n <p>The item must be in the original packaging.</p>\n </li>\n <li>\n <p>To complete your return, we require a receipt or proof of purchase.</p>\n </li>\n <li>\n <p>Only regular priced items may be refunded, sale items cannot be refunded.</p>\n </li>\n <li>\n <p>If the item in question was marked as a gift when purchased and shipped directly to you, you will receive a gift credit for the value of your return.</p>\n </li>\n</ul>\n\n<p><strong>Exchanges</strong> <em>(if applicable)</em></p>\n\n<p>We only replace items if they are defective or damaged. If you need to exchange it for the same item, send us an email at (Add Relevant Email Address) and send your item to: (Relevant Address).</p>\n\n<p><strong>Exempt Goods</strong></p>\n\n<p>The following are exempt from refunds:</p>\n\n<ul>\n <li>\n <p>Gift cards</p>\n </li>\n <li>\n <p>Some health and personal care items</p>\n </li>\n</ul>\n\n<p><strong>Partial refunds are granted</strong> <em>(if applicable)</em></p>\n\n<ul>\n <li>\n <p>Any item not in its original condition, is damaged or missing parts for reasons not due to our error.</p>\n </li>\n <li>\n <p>Any item that is returned more than 30 days after delivery.</p>\n </li>\n</ul>\n\n<p>Once your return is received and inspected, we will send you an email to notify you that we have received your returned item. We will also notify you of the approval or rejection of your refund.</p>\n\n<p>If you are approved, then your refund will be processed, and a credit will automatically be applied to your credit card or original method of payment, within a certain amount of days.</p>\n\n<p><strong>Late or missing refunds</strong></p>\n\n<ul>\n <li>\n <p>If you have not received a refund yet, first check your bank account again. Then contact your credit card company, it may take some time before your refund is officially posted.</p>\n </li>\n <li>\n <p>If you have done all of this and you still have not received your refund yet, please contact us at (email and or phone number)</p>\n </li>\n</ul>\n\n<p><strong>Shipping</strong></p>\n\n<ul>\n <li>\n <p>Please do not send the product back to the manufacturer. It must be sent to the following Address (Relevant Address).</p>\n </li>\n <li>\n <p>You will be responsible for paying for your own shipping costs for returning your item.</p>\n </li>\n <li>\n <p>Shipping costs are non-refundable! If you receive a refund, the cost of return shipping will be deducted from your refund.</p>\n </li>\n <li>\n <p>Depending on where you live, the time it may take for your exchanged product to reach you, may vary.</p>\n </li>\n <li>\n <p>Please see, we cannot guarantee that we will receive your returned item.</p>\n </li>\n</ul>', '', '', '<h3><strong>FAQ</strong></h3>\n\n<p> </p>\n\n<p><strong>Q1.     </strong><strong>Do you ship to my country?</strong></p>\n\n<p><strong>Ans.   </strong>Yes. We proudly ship worldwide! ???? Better yet, our tracked shipping is always 100% free of charge, with no minimum purchase! ?</p>\n\n<p>           We’ve shipped cute stationery free to over 200+ countries and we love adding more to the list!</p>\n\n<p>           See the next question for detailed shipping times.</p>\n\n<p><strong>Q2.     How long does shipping take? When will I receive my order?</strong></p>\n\n<p><strong>Ans.   </strong>It all depends on your country! Find your region and estimated delivery time in the table below.<br>\n<br>\n           Please note there are currently delays to some countries due to covid-19 lockdowns at the port of origin.</p>\n\n<table>\n <tbody>\n  <tr>\n   <td><strong>The following countries have restricted shipping due to covid-19:</strong><br>\n   <br>\n   Bolivia, Brazil, Brunei, Chile, Costa Rica, Cyprus, Egypt, Estonia, Georgia, Honduras, Iceland, India, Jamaica, Jersey, Kosovo, Kuwait, Lesotho, Maldives, Malta, Mauritius, Mongolia, Morocco, Peru, Philippines, Qatar, Réunion, Saudi Arabia, Serbia, South Africa, Sri Lanka.<br>\n   <br>\n   Orders to these countries will be shipped when country specific restrictions are lifted.</td>\n  </tr>\n </tbody>\n</table>\n\n<p><strong>Q3.     </strong><strong>My order has been dispatched, can I track it?</strong></p>\n\n<p><strong>Ans.   </strong>Once your order has been shipped, you’ll receive a tracking number via email. Note, it can take up to 7 days for shipping activity to update.</p>\n\n<p>           Have your tracking number to hand? You can <a href=\"https://notebooktherapy.com/pages/tracking?nopreview\">track your order&#39;s status here</a>.</p>\n\n<p><strong>Q4.     Do you offer a guarantee? Can I return my items?</strong></p>\n\n<p><strong>Ans.   </strong>Of course. We offer an extended 30 day guarantee! ??</p>\n\n<p>           If you aren’t 100% satisfied with your items, or received faulty goods, simply email our customer support team at  <a href=\"mailto: mail@axepertexhibits.com\">mail@axepertexhibits.com</a> Please include the email</p>\n\n<p>           address associated with the order </p>\n\n<p>           and describe the issue, include photos if possible. We always aim to respond in 3 days or less!</p>\n\n<p><strong>Q5.     Can I change or cancel my order?</strong></p>\n\n<p><strong>Ans.  </strong>Sure! You can cancel, or change your order within 12 hours of confirmation. Please contact us with your name and order number at: <a href=\"mailto: mail@axepertexhibits.com\">mail@axepertexhibits.com</a></p>\n\n<p>          After 12 hours, your order will have been processed and we won’t be able to make any changes or cancel it.</p>\n\n<p><strong>Q6.     What methods of payment do you take?</strong></p>\n\n<p><strong>Ans.   </strong>We accept ALL major credit cards, PayPal, and Apple Pay.</p>\n\n<p>           All payments are securely processed with 128-bit encryption - nice! ?</p>\n\n<p><strong>Q7.     Do you offer promotional or affiliate opportunities?</strong></p>\n\n<p><strong>Ans. </strong>  We do and we’d love to hear from you! ????</p>\n\n<p>           <a href=\"https://notebooktherapy.com/pages/bloggers\">Head here</a> for more information.</p>\n\n<p><strong>Q8.     Do I need to pay import duties?</strong></p>\n\n<p><strong>Ans.   </strong>Some packages may be subject to import duties depending on the country of receipt.<br>\n<br>\n           Please note, due to new EU VAT rules, there may be increased duty to pay on packages arriving to EU member states.</p>', '<p><strong>Our Belief</strong></p>\r\n\r\n<p>From the rich and diverse culture of India, we bring to you the feel of grandeur and celebration. Our handmade products are a tribute to our culture. Explore the handcrafted and highly functional range of bags for all your needs. Our products are 100% Vegan and Proudly Indian.</p>\r\n\r\n<p><strong>Our Vision</strong></p>\r\n\r\n<p>We want to take the rich Indian heritage in a modern avatar to everyone worldwide. We insist on being 100% Vegan and focus on making our products useful. Style with substance is key. We want our customers to make Zouk a part of their most cherished experiences, be it that promotion day in office or that fantasy vacation to Maldives or as a special gift to a loved one. </p>', 'https://www.facebook.com/rhythmicalchords', NULL, 'https://www.instagram.com/asli_zindagi1999/', 'https://youtube.com/rhythmicalchords', 500, 50, '', 'Delhi', 'India', 'New Delhi', 'Hi I\'m Anna Adame,It will be as simple as Occidental; in fact, it will be Occidental. To an English person, it will seem like simplified English, as a skeptical Cambridge friend of mine told me what Occidental is European languages are members of the same family.', '8285887941', '<script type=\"text/javascript\">\r\nvar Tawk_API=Tawk_API||{}, Tawk_LoadStart=new Date();\r\n(function(){\r\nvar s1=document.createElement(\"script\"),s0=document.getElementsByTagName(\"script\")[0];\r\ns1.async=true;\r\ns1.src=\'https://embed.tawk.to/62989c8a7b967b1179928a33/1g4i26vm8\';\r\ns1.charset=\'UTF-8\';\r\ns1.setAttribute(\'crossorigin\',\'*\');\r\ns0.parentNode.insertBefore(s1,s0);\r\n})();\r\n</script>', 0);

